1	import type {
2	  WorkspaceBusy,
3	  WorkspaceStamp,
4	  WorkspaceSwitchResult,
5	} from "@shared/types/workspaces";
6	import type { WorkspaceGate } from "./gate";
7	import type { Availability, RelocateOutcome } from "./registry";
8	
9	export interface SwitchDeps {
10	  gate: WorkspaceGate;
11	  activeId(): string;
12	  isKnown(id: string): boolean;
13	  readOnly(): boolean;
14	  /** Probes the target folder; resolves its id afterwards (a pending entry may adopt one). */
15	  availability(id: string): Promise<{ availability: Availability; id: string }>;
16	  /** What is writing into the active workspace right now, if anything (the LOCKED state). */
17	  busy(): WorkspaceBusy | null;
18	  /**
19	   * Ask every window to flush pending saves, resolve unsaved editors (Save, Discard or
20	   * Cancel) and close what belongs to the old workspace. False when one cancelled or timed out.
21	   */
22	  prepareWindows(): Promise<boolean>;
23	  /** The switch is off after `prepareWindows`: windows go back to normal. */
24	  abortWindows(): void;
25	  /** Dismiss pending quiet-capture toasts and drop their retained bytes (after `persistActive`). */
26	  dropPendingCaptures(): void;
27	  /** Store `activeId` and the mirrored `vaultDirectory`. */
28	  persistActive(id: string): Promise<void>;
29	  /** Window title, tray, `workspaces:changed` and `library:changed`. */
30	  afterCommit(stamp: WorkspaceStamp): void;
31	}
32	
33	let inFlight = false;
34	
35	/**
36	 * The switch transaction (ADR 0032, decision 7). Every switch entry point goes through it.
37	 * Anything that fails before the commit leaves the old workspace active and unchanged.
38	 *
39	 * The windows are asked to prepare BEFORE the gate closes: preparing means flushing an
40	 * editor's pending save, which is an item-scoped call that must still reach the old
41	 * workspace. Only then does the gate refuse new calls and wait for the running ones.
42	 */
43	export async function switchWorkspace(
44	  deps: SwitchDeps,
45	  id: string,
